def episode(identifier: str, split: str, domain: str, messages: list[str],
            ids: list[str], urgency: str, answer: str) -> dict:
    return {
        "id": identifier, "split": split, "domain": domain, "messages": messages,
        "expected_ids": [BY_SUFFIX[item]["id"] for item in ids],
        "urgency": urgency, "answer_ru": answer,
        "must_mention": [], "must_not": [],
        "source_support_ru": SOURCE_SUPPORT[domain][0],
        "source_urls": [SOURCE_SUPPORT[domain][1]],
        "annotation_status": "source_linked_author_draft_not_clinically_reviewed",
    }


