def project_cards(selected: list[dict]) -> list[dict]:
    return [{"id": card["id"], "name": card["name_ru"],
             "for": "; ".join(card["evidence_for"]),
             "against": "; ".join(card["evidence_against"])} for card in selected]


def compact_cards(messages: list[str]) -> list[dict]:
    return project_cards(retrieve(" ".join(messages), CARDS, count=4))


def main() -> None:
    ids = [item["id"] for item in CASES]
    assert len(CASES) == 42 and len(ids) == len(set(ids))
    assert {item["urgency"] for item in CASES} == {"routine", "prompt_review", "emergency"}
    for item in CASES:
        assert item["split"] in {"train", "validation"}
        assert item["source_urls"] and item["answer_ru"]
        available = {card["id"] for card in compact_cards(item["messages"])}
        assert set(item["expected_ids"]) <= available, (item["id"], item["expected_ids"], available)
    old_cases = []
    for name in ("eval_cases.json", "review_cases_240.json"):
        old_cases += json.loads((ROOT / "docs/model-led" / name).read_text(encoding="utf-8"))["cases"]
    old_messages = {message.casefold() for item in old_cases for message in item["messages"]}
    assert all(message.casefold() not in old_messages for item in CASES for message in item["messages"])

    folder = ROOT / "training/data"
    folder.mkdir(parents=True, exist_ok=True)
    bank = {"version": "0.2-author-draft", "clinical_review": "pending",
            "sources_checked_on": "2026-11-09", "cases": CASES}
    (folder / "casebook_v2.json").write_text(json.dumps(bank, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    train = []
    for item in CASES:
        if item["split"] != "train":
            continue
        context = {"episode_messages": item["messages"], "local_cards": compact_cards(item["messages"])}
        output = {"candidate_ids": item["expected_ids"], "urgency": item["urgency"],
                  "answer_ru": item["answer_ru"], "used_knowledge_ids": item["expected_ids"]}
        train.append({"case_id": item["id"], "messages": [
            {"role": "system", "content": SYSTEM_PROMPT_V2},
            {"role": "user", "content": json.dumps(context, ensure_ascii=False)},
            {"role": "assistant", "content": json.dumps(output, ensure_ascii=False)},
        ]})
    (folder / "multiturn_sft_v2.jsonl").write_text(
        "\n".join(json.dumps(item, ensure_ascii=False) for item in train) + "\n", encoding="utf-8")
    validation = {"version": "0.2-author-draft", "status": "fictional_not_clinically_reviewed",
                  "cases": [item for item in CASES if item["split"] == "validation"]}
    (folder / "validation_v2.json").write_text(json.dumps(validation, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    blind = {"version": "0.2-author-draft", "instruction": "Clinician: assign candidate IDs, urgency, rationale and next action without seeing author labels or model output.",
             "cases": [{"id": item["id"], "messages": item["messages"], "source_urls": item["source_urls"],
                        "reviewer_candidate_ids": None, "reviewer_urgency": None,
                        "reviewer_rationale": None, "reviewer_name": None, "reviewed_at": None}
                       for item in CASES]}
    (folder / "clinical_review_blind_v2.json").write_text(json.dumps(blind, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    digest = hashlib.sha256((folder / "multiturn_sft_v2.jsonl").read_bytes()).hexdigest()
    print(f"cases={len(CASES)} train={len(train)} validation={len(validation['cases'])} sha256={digest}")


if __name__ == "__main__":
    main()
